(() => {
"use strict";
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const app=$("#app"), cfg=window.TRANSFER_CONFIG||{};
const KEY="transfer69_preview_v1";
const blank=()=>({bookings:[],offers:[],drivers:[],profiles:{},settings:{offersEnabled:true,bellBookingEnabled:true,bellChatEnabled:true,comfort:200,business:350,vip:500},session:null,messages:[],notifications:[],documents:[],financeRows:[],commissionPercent:null});
const supabaseReady=!!(window.supabase&&cfg.supabaseUrl&&cfg.supabaseAnonKey);
const sb=supabaseReady?window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
let state=load(),settingsTab="profile",authUser=null,authProfile=null,otpPending=false,authBusy=false,activeChat=null,driverPinUnlocked=false,driverGpsWatch=null,driverGpsLastSent=0,trackingIntervals=[];
const driverPinKey=email=>"transfer_driver_pin_v2_"+String(email||"").toLowerCase();
async function hashDriverPin(pin,saltHex){const salt=saltHex?Uint8Array.from(saltHex.match(/.{2}/g).map(x=>parseInt(x,16))):crypto.getRandomValues(new Uint8Array(16));const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(pin),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt,iterations:150000,hash:"SHA-256"},key,256);const hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("");return {v:2,salt:hex(salt),hash:hex(bits)}}
async function verifyDriverPin(pin){const key=driverPinKey(me()?.email),raw=localStorage.getItem(key);if(raw){try{const saved=JSON.parse(raw);if(saved.v===2){const check=await hashDriverPin(pin,saved.salt);return check.hash===saved.hash}}catch(e){}}const legacy=localStorage.getItem("transfer_driver_pin_v1_"+String(me()?.email||"").toLowerCase());if(legacy&&legacy===pin){localStorage.setItem(key,JSON.stringify(await hashDriverPin(pin)));localStorage.removeItem("transfer_driver_pin_v1_"+String(me()?.email||"").toLowerCase());return true}return false}
state.session=null;state.settings={...blank().settings,...(state.settings||{})};
function load(){try{return {...blank(),...JSON.parse(localStorage.getItem(KEY)||"{}")}}catch(e){return blank()}}
function save(){const safe={...state,session:null};localStorage.setItem(KEY,JSON.stringify(safe))}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function money(v){return `${Number(v||0).toLocaleString()} SAR`}
function pickupMapUrl(b){let q=(b.pickupLat!=null&&b.pickupLng!=null)?`${b.pickupLat},${b.pickupLng}`:b.pickup;return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(q)}&travelmode=driving`}
function role(){let parts=location.pathname.replace(/\/+$/ ,"").split("/").filter(Boolean);let p=parts[0]||"";return ["customer","driver","admin","choose"].includes(p)?p:"home"}
function go(p){history.pushState({},"",p);render()}window.addEventListener("popstate",render);
function me(){return state.session}function profile(){return state.profiles[me()?.email]||{}}
function setProfile(p){state.profiles[me().email]={...profile(),...p};save()}
function myNotifications(){return (state.notifications||[]).slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))}
function notificationsPanel(){let ns=myNotifications();return `<section class="section card"><div class="section-title"><h2>Notifications</h2><span class="pill">${ns.filter(n=>!n.is_read).length} new</span></div>${ns.length?ns.slice(0,15).map(n=>`<div class="notice"><b>${esc(n.title)}</b><p>${esc(n.body)}</p><small>${new Date(n.created_at).toLocaleString()}</small>${!n.is_read?` <button class="btn btn-quiet btn-small" data-read-notification="${n.id}">Mark read</button>`:""}</div>`).join(""):`<div class="empty">No notifications yet.</div>`}</section>`}
async function openChat(bookingId,asRole){activeChat={bookingId,asRole};let b=state.bookings.find(x=>x.id===bookingId),area=$("#chat-area");if(!b||!b.acceptedOffer||!area)return;area.innerHTML='<div class="empty">Loading secure chat…</div>';try{const {data,error}=await sb.from('vip_messages').select('id,booking_id,sender_id,body,created_at').eq('booking_id',bookingId).order('created_at',{ascending:true});dbError(error);const relevant=data||[];area.innerHTML=`<p class="hint">Private chat for booking ${esc(b.id)} · ${esc(b.pickup)} → ${esc(b.dropoff)}. Phone numbers are never shown.</p><div id="chat-log">${relevant.map(m=>`<div class="msg ${m.sender_id===me().id?"mine":""}"><b>${m.sender_id===me().id?"You":"Other participant"}:</b> ${esc(m.body)}</div>`).join("")||`<div class="empty">No messages yet. Start the conversation.</div>`}</div><form id="send-chat-form"><div class="field"><input id="chat-text" maxlength="2000" placeholder="Write a message" required></div><button id="send-chat" class="btn btn-small">Send message</button>${asRole==="customer"?` <button type="button" id="chat-bell" class="btn btn-outline btn-small">🔔 Alert driver</button>`:""}</form>`;const chatBell=$('#chat-bell');if(chatBell)chatBell.onclick=async()=>{try{const {error:be}=await sb.rpc('vip_customer_alert_assigned_driver',{p_booking_id:bookingId});dbError(be);alert('The assigned driver has been alerted.')}catch(err){alert('Driver alert failed: '+err.message)}};$('#send-chat-form').onsubmit=async e=>{e.preventDefault();let input=$('#chat-text'),body=input.value.trim();if(!body)return;$('#send-chat').disabled=true;try{const {error:ie}=await sb.from('vip_messages').insert({booking_id:bookingId,sender_id:me().id,body});dbError(ie);await openChat(bookingId,asRole)}catch(err){alert('Message could not be sent: '+err.message);$('#send-chat').disabled=false}};}catch(err){area.innerHTML=`<div class="notice">Chat could not be loaded: ${esc(err.message)}</div>`}}
async function uploadStorageFile(bucket,file,folder){if(!file||!file.size)return null;if(file.size>(bucket==='transfer-driver-documents'?15:10)*1024*1024)throw new Error('File is too large. Maximum size is '+(bucket==='transfer-driver-documents'?15:10)+' MB.');const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-90)||'upload';const path=`${me().id}/${folder}/${Date.now()}_${safe}`;const {error}=await sb.storage.from(bucket).upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});dbError(error);return path}
async function saveDriverDocument(type,file){if(!file||!file.size)return null;const path=await uploadStorageFile('transfer-driver-documents',file,type);const {error}=await sb.from('vip_driver_documents').insert({driver_id:me().id,document_type:type,file_path:path});dbError(error);return path}
async function updateRideStatus(id,status,cashCollected){if(status==='completed'){const {error}=await sb.rpc('vip_complete_ride',{p_booking_id:id,p_cash_collected:!!cashCollected});dbError(error);return}const {error}=await sb.rpc('vip_update_ride_status',{p_booking_id:id,p_status:status});dbError(error)}
async function removeOffer(id){const {error}=await sb.rpc('vip_admin_cancel_offer',{p_offer_id:id});dbError(error)}

function currentDriver(){return state.drivers.find(d=>d.email===me()?.email)||{}}
function header(){let s=me();$("#session-label").textContent=s?`${s.role} · ${s.email}`:(supabaseReady?"Secure sign-in":"Setup required");$("#logout-btn").classList.toggle("hidden",!s);$("#settings-shortcut").classList.toggle("hidden",!s)}
$("#logout-btn").onclick=async()=>{driverPinUnlocked=false;await stopDriverGps();if(sb)await sb.auth.signOut();authUser=null;authProfile=null;state.session=null;go("/")};
$("#settings-shortcut").onclick=()=>go("/"+me().role+"/settings");
function home(){return auth("home")}
function roleChooser(){return `<section class="auth-wrap"><div class="card role-choice-card"><div class="eyebrow">WELCOME TO TRANSFER</div><h1>Choose how to continue</h1><p class="hint">Use the same Transfer account. Driver access becomes active after Admin approves your application.</p><div class="grid"><button class="btn" data-select-role="customer">Continue as Customer</button><button class="btn btn-outline" data-select-role="driver">Continue as Driver</button></div><p class="smallprint">Administrator access is protected and is available only to the authorized admin account.</p><button class="btn btn-quiet" id="choose-signout">Sign out</button></div></section>`}
function auth(r){
 const label=r==="home"?"Transfer":r[0].toUpperCase()+r.slice(1);
 if(!supabaseReady)return `<div class="auth-wrap"><div class="card"><h1>Secure sign-in setup required</h1><p class="hint">Add the Supabase Project URL and publishable key to config.js. No demo login is available in this build.</p><button class="btn btn-quiet" data-go="/">Back</button></div></div>`;
 if(otpPending)return `<div class="auth-wrap"><div class="card"><div class="eyebrow">EMAIL VERIFICATION</div><h1>Enter your 6-digit code</h1><p class="hint">We sent a sign-in code to <b>${esc(window.transferOtpEmail||"")}</b>.</p><form id="otp-form"><div class="field"><label>One-time password</label><input name="token" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required placeholder="123456"></div><button class="btn" type="submit">Verify and continue</button></form><div class="notice">Your OTP may be in your spam folder.</div><button class="btn btn-quiet" id="resend-otp">Resend code</button><button class="btn btn-quiet" data-go="/${r}">Change email</button><p id="auth-status" class="smallprint" role="status"></p></div></div>`;
 return `<div class="auth-wrap"><div class="card"><div class="eyebrow">${label} access</div><h1>${label} sign in</h1><p class="hint">Sign in securely with your email. Your phone number is private and is not shown to other users.</p><form id="auth-form"><div class="field"><label>Full name</label><input name="name" required maxlength="120" placeholder="Your name"></div><div class="field"><label>Phone number</label><input name="phone" type="tel" required maxlength="30" placeholder="+966…"></div><div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="name@example.com"></div><button class="btn" type="submit">Send email OTP</button></form><div class="notice">Your OTP may be in your spam folder.</div><p id="auth-status" class="smallprint" role="status"></p><p class="smallprint">Admin access is granted only to accounts authorized in the protected database. Choosing a Driver login does not approve a driver account.</p><button class="btn btn-quiet" data-go="/">Back</button></div></div>`
}
async function loadVerifiedProfile(user){
 const {data,error}=await sb.from("vip_profiles").select("id,email,full_name,role,account_type,phone").eq("id",user.id).single();
 if(error)throw new Error("Your account profile is not ready. Ask the administrator to check the Transfer profile setup. "+error.message);
 const meta=user.user_metadata||{};if((meta.phone&&!data.phone)||(meta.full_name&&!data.full_name)){const patch={};if(meta.phone&&!data.phone)patch.phone=meta.phone;if(meta.full_name&&!data.full_name)patch.full_name=meta.full_name;const {error:profileError}=await sb.from("vip_profiles").update(patch).eq("id",user.id);if(profileError)console.warn("Could not save OTP profile metadata:",profileError.message);else Object.assign(data,patch);}
 let admin=false;const {data:a,error:ae}=await sb.rpc("vip_is_admin");if(!ae)admin=!!a;
 let actualRole=admin?"admin":data.role;
 if(actualRole!=="admin"&&!['customer','driver'].includes(actualRole))throw new Error("This account does not have an approved app role.");
 if(role()==="admin"&&!admin)throw new Error("This email is not authorized as an administrator.");
 // Customer accounts may enter the Driver onboarding area; the database keeps them unapproved/offline until Admin approval.
 if(role()==="driver"&&actualRole==="customer")actualRole="driver";
 if(role()==="driver"&&actualRole!=="driver")throw new Error("Driver access is not active.");
 if(role()==="customer"&&actualRole!=="customer")throw new Error("This account is not registered for Customer access.");
 authUser=user;authProfile=data;state.session={role:admin?"admin":(role()==="home"||role()==="choose"?"choose":actualRole),email:user.email,id:user.id};
 state.profiles[user.email]={...(state.profiles[user.email]||{}),name:data.full_name||"",phone:data.phone||""};
 save();
}
function dbError(error, fallback="Database request failed") { if(error) throw new Error(error.message||fallback); }
function mapBooking(x){const dt=x.pickup_at?new Date(x.pickup_at):null;return {id:x.id,customerId:x.customer_id,customerEmail:me()?.email,kind:x.booking_type||"Now Booking",pickup:x.pickup,dropoff:x.destination,pickupLat:x.pickup_latitude,pickupLng:x.pickup_longitude,date:dt&&!isNaN(dt)?dt.toLocaleDateString():"",time:dt&&!isNaN(dt)?dt.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):"",category:x.category||"Any category",passengers:String(x.passengers||1),notes:x.notes||"",status:x.status,acceptedOffer:x.accepted_offer_id,createdAt:x.created_at};}
function mapOffer(x){return {id:x.id,bookingId:x.booking_id,driverId:x.driver_id,vehicleId:x.vehicle_id,driverEmail:x.driver_id===me()?.id?me().email:"",driverName:x.driver_name||"Transfer driver",vehicle:x.vehicle_model||"Vehicle details pending",photo:x.vehicle_photo_url||"",category:x.vehicle_category||"Comfort",plate:x.vehicle_plate||"",price:Number(x.price_sar),eta:x.eta_text||"",status:x.offer_status||x.status,createdAt:x.created_at};}
async function refreshData(quiet=false){
 if(!sb||!me()?.id)return;
 try{
  const [settingsRes,bookRes,appRes,vehicleRes]=await Promise.all([
   sb.from('vip_settings').select('*').eq('id',1).maybeSingle(),
   (me().role==='customer'?sb.from('vip_bookings').select('*').eq('customer_id',me().id):sb.from('vip_bookings').select('*')) .order('created_at',{ascending:false}),
   me().role==='admin'?sb.from('vip_driver_applications').select('*').order('created_at',{ascending:false}):sb.from('vip_driver_applications').select('*').eq('driver_id',me().id).maybeSingle(),
   me().role==='driver'?sb.from('vip_vehicles').select('*').eq('driver_id',me().id):sb.from('vip_vehicles').select('*')
  ]);
  dbError(settingsRes.error);dbError(bookRes.error);dbError(appRes.error);dbError(vehicleRes.error);
  if(settingsRes.data){let z=settingsRes.data;state.settings={...state.settings,offersEnabled:z.offers_enabled,pricingMode:z.pricing_mode,comfort:Number(z.comfort_price),business:Number(z.business_price),vip:Number(z.vip_price)};}
  state.bookings=(bookRes.data||[]).map(mapBooking);
  const apps=me().role==='admin'?(appRes.data||[]):(appRes.data?[appRes.data]:[]);
  const vehicles=vehicleRes.data||[];
  state.drivers=apps.map(a=>{let v=vehicles.find(v=>v.driver_id===a.driver_id);return {id:a.driver_id,email:a.driver_id===me().id?me().email:a.driver_id,legalName:a.vehicle_model?"": "",vehicle:a.vehicle_model||v?.model||"",year:a.vehicle_year||"",category:a.vehicle_category||v?.category||"Comfort",plate:a.vehicle_plate||v?.plate||"",photo:v?.photo_url||a.vehicle_photo_url||"",approved:a.status==='approved',applied:true,status:a.status,online:false,vehicleId:v?.id};});
  if(me().role==='driver'){let {data:prof}=await sb.from('vip_profiles').select('is_available,full_name,email,commission_percent').eq('id',me().id).single();let d=state.drivers[0]||{id:me().id,email:me().email};d.online=!!prof?.is_available;d.approved=d.status==='approved';d.legalName=prof?.full_name||d.legalName;d.email=me().email;d.commissionPercent=prof?.commission_percent==null?null:Number(prof.commission_percent);state.commissionPercent=d.commissionPercent;state.drivers=[d];}
  if(me().role==='admin'){const driverIds=state.drivers.map(d=>d.id);const {data:profiles,error:pe}=driverIds.length?await sb.from('vip_profiles').select('id,email,full_name,commission_percent').in('id',driverIds):{data:[],error:null};dbError(pe);for(const d of state.drivers){const p=(profiles||[]).find(x=>x.id===d.id);if(p){d.email=p.email;d.legalName=p.full_name||d.legalName;d.commissionPercent=p.commission_percent==null?null:Number(p.commission_percent)}}}
  const ledgerQuery=sb.from('vip_driver_ledger').select('*').order('completed_at',{ascending:false});
  const {data:ledger,error:le}=me().role==='driver'?await ledgerQuery.eq('driver_id',me().id):me().role==='admin'?await ledgerQuery: {data:[],error:null};dbError(le);state.financeRows=ledger||[];
  let offerRows=[];
  if(me().role==='customer'){
   for(const b of state.bookings){const {data,error}=await sb.rpc('vip_customer_offer_cards',{p_booking_id:b.id});if(error)throw error;offerRows.push(...(data||[]).map(mapOffer));}
  }else if(me().role==='driver'){
   const {data,error}=await sb.from('vip_offers').select('*').eq('driver_id',me().id).order('created_at',{ascending:false});dbError(error);offerRows=(data||[]).map(mapOffer);
  }else{
   const {data,error}=await sb.from('vip_offers').select('*').order('created_at',{ascending:false});dbError(error);offerRows=(data||[]).map(mapOffer);
  }
  state.offers=offerRows;
  const {data:ns,error:ne}=await sb.from('vip_notifications').select('*').order('created_at',{ascending:false}).limit(50);dbError(ne);state.notifications=ns||[];
  if(me().role==='admin'){const {data:docs,error:de}=await sb.from('vip_driver_documents').select('id,driver_id,document_type,file_path,created_at').order('created_at',{ascending:false});dbError(de);state.documents=docs||[];}
  save();
  if(!quiet){render();if(activeChat&&state.bookings.some(b=>b.id===activeChat.bookingId&&b.acceptedOffer))await openChat(activeChat.bookingId,activeChat.asRole)}
 }catch(e){console.error('Transfer refresh:',e);if(!quiet)alert('Could not load live Transfer data: '+e.message);}
}
let liveChannel=null;
let liveRefreshTimer=null,lastLiveRefresh=0;
function startLiveUpdates(){if(!sb||!me()?.id)return;if(liveChannel)sb.removeChannel(liveChannel);liveChannel=sb.channel('transfer-live-'+me().id)
 .on('postgres_changes',{event:'*',schema:'public',table:'vip_bookings'},()=>refreshData(false))
 .on('postgres_changes',{event:'*',schema:'public',table:'vip_offers'},()=>refreshData(false))
 .on('postgres_changes',{event:'*',schema:'public',table:'vip_settings'},()=>refreshData(false))
 .on('postgres_changes',{event:'*',schema:'public',table:'vip_driver_applications'},()=>refreshData(false))
 .on('postgres_changes',{event:'*',schema:'public',table:'vip_messages'},()=>refreshData(false))
 .on('postgres_changes',{event:'*',schema:'public',table:'vip_notifications',filter:'recipient_id=eq.'+me().id},()=>refreshData(false))
 .subscribe();
 if(liveRefreshTimer)clearInterval(liveRefreshTimer);
 liveRefreshTimer=setInterval(()=>{if(document.visibilityState==='visible'&&me()?.id)refreshData(false)},20000);
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&me()?.id)refreshData(false)});
}
async function submitBooking(payload){const row={customer_id:me().id,pickup:payload.pickup,destination:payload.dropoff,pickup_at:payload.pickupAt,category:payload.category==='Any category'?null:payload.category,passengers:payload.passengers,notes:payload.notes||null,status:'open',booking_type:payload.kind,pickup_latitude:payload.pickupLat,pickup_longitude:payload.pickupLng};const {data,error}=await sb.from('vip_bookings').insert(row).select().single();dbError(error);const alertResult=await sb.rpc('vip_customer_alert_drivers',{p_booking_id:data.id});if(alertResult.error)console.warn('Driver alert was not sent:',alertResult.error.message);return mapBooking(data);}
async function submitDriverOffer(b,price,eta){
 const {data:vehicle,error:ve}=await sb.from('vip_vehicles').select('id').eq('driver_id',me().id).eq('approved',true).limit(1).maybeSingle();
 dbError(ve);
 if(!vehicle?.id)throw new Error('Save your vehicle details after your driver account is approved before sending an offer.');
 // One offer per driver per booking: update the existing pending offer instead
 // of inserting a duplicate row and triggering the unique booking/driver key.
 const {data:existing,error:ee}=await sb.from('vip_offers').select('id,status').eq('booking_id',b.id).eq('driver_id',me().id).maybeSingle();
 dbError(ee);
 if(existing&&String(existing.status||'').toLowerCase()==='accepted')throw new Error('Your offer for this booking has already been accepted.');
 if(existing){const {error}=await sb.rpc('vip_driver_update_offer',{p_offer_id:existing.id,p_price:Number(price),p_eta:eta||null});dbError(error);return {id:existing.id,booking_id:b.id,driver_id:me().id,price_sar:Number(price),eta_text:eta||null,status:'pending'};}
 const row={booking_id:b.id,driver_id:me().id,vehicle_id:vehicle.id,price_sar:Number(price),eta_text:eta||null,status:'pending'};
 const {data,error}=await sb.from('vip_offers').insert(row).select().single();
 dbError(error);
 return data;
}
async function stopDriverGps(){if(driverGpsWatch!==null&&navigator.geolocation){navigator.geolocation.clearWatch(driverGpsWatch);driverGpsWatch=null;}if(sb&&me()?.role==='driver'){try{await sb.rpc('vip_driver_clear_location')}catch(e){console.warn('Could not clear driver GPS location:',e.message)}}}
function hasActiveDriverRide(){return state.bookings.some(b=>['accepted','driver_arrived','in_progress'].includes(b.status)&&state.offers.some(o=>o.bookingId===b.id&&o.driverId===me()?.id&&o.status==='accepted'));}
function startDriverGps(){if(!sb||!navigator.geolocation||me()?.role!=='driver'||!currentDriver().online||!currentDriver().approved||!hasActiveDriverRide())return;if(driverGpsWatch!==null)return;driverGpsWatch=navigator.geolocation.watchPosition(async pos=>{const now=Date.now();if(now-driverGpsLastSent<10000)return;driverGpsLastSent=now;try{const {error}=await sb.rpc('vip_driver_update_location',{p_latitude:pos.coords.latitude,p_longitude:pos.coords.longitude,p_accuracy_m:pos.coords.accuracy||null});dbError(error)}catch(e){console.warn('Driver GPS update failed:',e.message)}},err=>{console.warn('Driver GPS unavailable:',err.message);const status=$('#driver-gps-status');if(status)status.textContent='GPS unavailable: '+err.message},{enableHighAccuracy:true,maximumAge:5000,timeout:20000});}
async function initTrackingMaps(){if(!window.L||!sb)return;trackingIntervals.forEach(clearInterval);trackingIntervals=[];for(const b of state.bookings.filter(x=>x.acceptedOffer&&['accepted','driver_arrived','in_progress'].includes(x.status))){const box=$('#tracking-map-'+b.id);if(!box||box.dataset.ready)continue;box.dataset.ready='1';const map=L.map(box,{scrollWheelZoom:false}).setView([24.7136,46.6753],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);let marker=null;const status=$('#tracking-status-'+b.id);const update=async()=>{try{const {data,error}=await sb.from('vip_driver_locations').select('latitude,longitude,accuracy_m,updated_at').eq('driver_id',state.offers.find(o=>o.id===b.acceptedOffer)?.driverId||'').maybeSingle();dbError(error);if(data){const point=[data.latitude,data.longitude];if(!marker)marker=L.marker(point).addTo(map).bindPopup('Assigned driver');else marker.setLatLng(point);map.setView(point,15);const age=Math.max(0,Math.round((Date.now()-new Date(data.updated_at).getTime())/1000));if(status)status.textContent=age<60?`Driver location updated ${age} seconds ago.`:`Last location update was ${Math.floor(age/60)} minutes ago.`}else if(status)status.textContent='Waiting for the driver to share GPS location…'}catch(e){if(status)status.textContent='Live location is not available: '+e.message}};await update();trackingIntervals.push(setInterval(update,15000));}}
async function updateAvailability(value){const {error}=await sb.rpc('vip_set_driver_availability',{p_available:value});dbError(error);if(!value)await stopDriverGps();}
async function acceptOffer(b,o){const {error}=await sb.rpc('vip_accept_offer',{p_offer_id:o.id});dbError(error);}
async function cancelBooking(id){const {error}=await sb.rpc('vip_cancel_booking',{p_booking_id:id});dbError(error);}
function showAuthError(message){const el=$("#auth-status");if(el)el.textContent=message;else alert(message)}
async function beginEmailOtp(form){if(authBusy)return;authBusy=true;const btn=form.querySelector("button[type=submit]");if(btn)btn.disabled=true;try{const fd=new FormData(form),email=String(fd.get("email")).trim().toLowerCase(),name=String(fd.get("name")).trim(),phone=String(fd.get("phone")).trim();window.transferOtpEmail=email;window.transferOtpMeta={name,phone};const {error}=await sb.auth.signInWithOtp({email,options:{shouldCreateUser:true,data:{full_name:name,phone}}});if(error)throw error;otpPending=true;render()}catch(e){showAuthError(e.message||"Could not send OTP.")}finally{authBusy=false}}
async function verifyEmailOtp(form){if(authBusy)return;authBusy=true;const btn=form.querySelector("button[type=submit]");if(btn)btn.disabled=true;try{const token=String(new FormData(form).get("token")).trim();const {data,error}=await sb.auth.verifyOtp({email:window.transferOtpEmail,token,type:"email"});if(error)throw error;otpPending=false;await loadVerifiedProfile(data.user);if(state.session.role==="admin"){await refreshData(true);startLiveUpdates();go("/admin")}else go("/choose")}catch(e){showAuthError(e.message||"Verification failed.")}finally{authBusy=false;if(btn)btn.disabled=false}}

function bookings(){return state.bookings.filter(b=>b.status!=="cancelled")}
function offerList(){let mine=state.bookings.filter(b=>b.customerId===me()?.id && b.status==='open').map(b=>b.id);let arr=state.offers.filter(o=>o.status==='pending'&&mine.includes(o.bookingId)).sort((a,b)=>a.price-b.price).slice(0,Math.max(1,Math.min(4,Number(state.settings.offerLimit||4))));if(!arr.length)return `<div class="empty">No offers yet. Approved online drivers will appear here after sending their prices.</div>`;return arr.map(o=>`<div class="offer">${o.photo?`<img src="${esc(o.photo)}" alt="Vehicle photo" style="width:88px;height:66px;object-fit:cover;border-radius:8px">`:""}<div><b>${esc(o.vehicle)}</b><small>${esc(o.category)} · ${esc(o.eta||"Pickup time to be confirmed")}</small><small>${esc(o.driverName||"Transfer driver")} · Plate hidden until acceptance</small></div><div><div class="price">${money(o.price)}</div><button class="btn btn-small" data-accept="${o.id}">Accept offer</button></div></div>`).join("")}
function customer(){let bs=bookings().filter(b=>b.customerId===me()?.id);return `<div class="page-head"><div><div class="eyebrow">Customer area</div><h1>Book your car</h1><p>Airport transfer · Airport shuttle · City-to-city</p></div><button class="btn btn-outline" data-go="/customer/settings">Settings</button></div>${notificationsPanel()}
<div class="card"><div class="tabs"><button class="tab active" data-kind="Now Booking">Now Booking</button><button class="tab" data-kind="Later Booking">Later Booking</button><button class="tab" data-kind="Airport Transfer">Airport Transfer</button></div>
<form id="booking-form"><input type="hidden" name="kind" value="Now Booking"><div class="form-grid"><div class="field"><label>Pickup address / airport / location</label><input name="pickup" id="pickup-address" required placeholder="Enter exact pickup address or landmark"><button type="button" id="use-pickup-location" class="btn btn-outline btn-small">Use my current pickup location</button><small id="pickup-location-status" class="hint">Choose a pickup point on the map, search an address, or share your current GPS location.</small><div id="pickup-map" class="transfer-map" role="application" aria-label="Choose pickup location on map"></div><input type="hidden" name="pickupLat" id="pickup-lat"><input type="hidden" name="pickupLng" id="pickup-lng"></div><div class="field"><label>Destination</label><input name="dropoff" required placeholder="e.g. Riyadh city"></div><div class="field later-field hidden"><label>Pickup date</label><input name="date" type="date"></div><div class="field later-field hidden"><label>Pickup time</label><input name="time" type="time"></div><div class="field"><label>Vehicle category</label><select name="category"><option>Any category</option><option>Comfort</option><option>Business</option><option>VIP</option></select></div><div class="field"><label>Passengers</label><select name="passengers"><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option>6+</option></select></div></div><div class="action-row"><button class="btn" type="submit">Create booking request</button></div><p class="smallprint">${state.settings.bellBookingEnabled?"Approved online drivers are notified automatically as soon as you create the booking.":"Driver notifications are automatic; only approved online drivers receive new requests."}</p></form></div>
<section class="section"><div class="section-title"><h2>Driver price offers</h2><span class="pill">Lowest price first · Up to 4</span></div><div id="offers">${offerList()}</div></section>
<section class="section"><h2>Your bookings</h2>${bs.length?bs.map(b=>{let accepted=state.offers.find(o=>o.id===b.acceptedOffer);return `<div class="card section"><b>${esc(b.kind)}</b><p>${esc(b.pickup)} → ${esc(b.dropoff)}</p><p><a class="btn btn-outline btn-small" href="${pickupMapUrl(b)}" target="_blank" rel="noopener">View pickup in Google Maps ↗</a></p><span class="pill">${esc(b.status)}</span>${b.status==="open"?`<button class="btn btn-outline btn-small" data-bell-booking="${b.id}">🔔 Alert online drivers</button>`:""}${accepted?`<p><b>Accepted vehicle:</b> ${esc(accepted.vehicle)} · ${money(accepted.price)}<br><b>Plate:</b> ${esc(accepted.plate||"Driver plate shared after acceptance")}</p><button class="btn btn-outline btn-small" data-chat="${b.id}">Open chat</button>`:""}<button class="btn btn-quiet btn-small" data-cancel-booking="${b.id}">Cancel booking</button></div>`}).join(""):`<div class="empty">Your bookings will appear here.</div>`}</section>
<section class="section"><h2>Ride status</h2>${bs.length?bs.map(b=>{let o=state.offers.find(x=>x.id===b.acceptedOffer);return `<div class="card section"><b>${esc(b.pickup)} → ${esc(b.dropoff)}</b><p><span class="pill">${esc(b.status)}</span> ${o?`<span class="pill">${esc(o.vehicle)}</span>`:""}</p>${o?`<p>Driver: ${esc(o.driverName||"Driver")} · ${esc(o.eta||"ETA pending")}<br>Plate: ${esc(o.plate||"Not provided")}</p>${["accepted","driver_arrived","in_progress"].includes(b.status)?`<div class="tracking-card"><b>Driver live location</b><p class="hint" id="tracking-status-${b.id}">Waiting for the driver to share GPS location…</p><div id="tracking-map-${b.id}" class="transfer-map" aria-label="Assigned driver live location map"></div></div>`:""}`:""}${b.status==="completed"&&!b.rating?`<form class="rating-form" data-rating="${b.id}"><div class="field"><label>Rate your driver (1–5 stars)</label><select name="stars"><option value="5">★★★★★ — 5</option><option value="4">★★★★ — 4</option><option value="3">★★★ — 3</option><option value="2">★★ — 2</option><option value="1">★ — 1</option></select></div><div class="field"><label>Comment (optional)</label><input name="comment" placeholder="How was your ride?"></div><button class="btn btn-small">Submit rating</button></form>`:b.rating?`<p><b>Your rating:</b> ${"★".repeat(b.rating.stars)}${"☆".repeat(5-b.rating.stars)} ${esc(b.rating.comment||"")}</p>`:""}</div>`}).join(""):`<div class="empty">Ride status will appear after an offer is accepted.</div>`}</section>
<section class="section"><h2>Private in-app chat</h2><div class="chatbox"><p class="hint">Chat is available only after accepting an offer. Phone numbers are not displayed.</p><div id="chat-area"><div class="empty">Accept an offer, then open its chat from your booking.</div></div></div></section>`}
function financeTotals(rows){const total=key=>rows.reduce((n,r)=>n+Number(r[key]||0),0);const collected=rows.filter(r=>r.cash_collected);const uncollected=rows.filter(r=>!r.cash_collected);const balance=uncollected.reduce((n,r)=>n+Number(r.driver_net_sar||0),0)-collected.reduce((n,r)=>n+Number(r.commission_sar||0),0);return {work:total('fare_sar'),commission:total('commission_sar'),net:total('driver_net_sar'),cash:collected.reduce((n,r)=>n+Number(r.fare_sar||0),0),uncash:uncollected.reduce((n,r)=>n+Number(r.fare_sar||0),0),balance};}
function driverFinancePanel(){const rows=state.financeRows||[],t=financeTotals(rows),pct=state.commissionPercent;return `<section class="section card"><h2>My Balance & Payment History</h2><div class="statrow"><div class="stat"><b>${money(t.work)}</b><span>Total completed work</span></div><div class="stat"><b>${money(t.commission)}</b><span>Total commission</span></div><div class="stat"><b>${money(t.net)}</b><span>Net after commission</span></div></div><p><b>My commission rate:</b> ${pct==null?'Not assigned by Admin':pct+'%'}</p><p><b>Cash collected:</b> ${money(t.cash)} · <b>Not collected:</b> ${money(t.uncash)}</p><div class="notice"><b>Estimated balance: <span>${t.balance>=0?'+':''}${money(t.balance)}</span></b><br>Positive = net fare still uncollected. Negative = commission due on cash already collected. This is an accounting balance, not a bank transfer confirmation.</div><h3>Completed ride ledger</h3>${rows.length?rows.map(r=>`<div class="offer"><div><b>${money(r.fare_sar)} · ${Number(r.commission_percent)}% commission (${money(r.commission_sar)})</b><small>Net: ${money(r.driver_net_sar)} · Cash: ${r.cash_collected?'Collected':'Not collected'} · ${new Date(r.completed_at).toLocaleString()}</small></div></div>`).join(''):`<div class="empty">No completed rides recorded yet.</div>`}</section>`;}
function adminFinancePanel(){const rows=state.financeRows||[],t=financeTotals(rows);const groups=[...new Set(rows.map(r=>r.driver_id))].map(id=>{const rs=rows.filter(r=>r.driver_id===id),z=financeTotals(rs),d=state.drivers.find(x=>x.id===id);return {id,rs,z,d}});return `<section class="section card"><h2>Driver Finance & Commission</h2><div class="statrow"><div class="stat"><b>${money(t.work)}</b><span>Total customer fares</span></div><div class="stat"><b>${money(t.commission)}</b><span>Total commission</span></div><div class="stat"><b>${money(t.cash)}</b><span>Cash collected</span></div><div class="stat"><b>${money(t.uncash)}</b><span>Cash outstanding</span></div></div><p><b>Estimated net balance:</b> ${t.balance>=0?'+':''}${money(t.balance)}</p><h3>Set each driver's commission</h3>${state.drivers.length?state.drivers.map(d=>`<div class="offer"><div><b>${esc(d.legalName||d.email||d.id)}</b><small>Current rate: ${d.commissionPercent==null?'Not set':d.commissionPercent+'%'}</small></div><select data-commission-driver="${d.id}" aria-label="Commission percentage"><option value="">Choose rate</option><option value="5" ${d.commissionPercent===5?'selected':''}>5%</option><option value="10" ${d.commissionPercent===10?'selected':''}>10%</option></select><button class="btn btn-small" data-save-commission="${d.id}">Save</button></div>`).join(''):`<div class="empty">No driver profiles found.</div>`}<h3>Per-driver totals</h3>${groups.length?groups.map(g=>`<div class="offer"><div><b>${esc(g.d?.legalName||g.d?.email||g.id)}</b><small>Work ${money(g.z.work)} · Commission ${money(g.z.commission)} · Net ${money(g.z.net)} · Cash ${money(g.z.cash)} · Uncollected ${money(g.z.uncash)}</small></div></div>`).join(''):`<div class="empty">No completed rides recorded yet.</div>`}</section>`;}
function driver(){let d=currentDriver(),bs=bookings().filter(b=>b.status==='open'&&d.approved&&d.online&&(!d.category||!b.category||b.category==='Any category'||b.category===d.category)),history=bookings().filter(b=>state.offers.some(o=>o.bookingId===b.id&&o.driverId===me().id&&o.status==='accepted'));return `<div class="page-head"><div><div class="eyebrow">Driver area</div><h1>Driver dashboard</h1><p>Applications · Requests · Vehicle · Offers</p></div><div class="driver-top-actions"><span id="driver-status-pill" class="pill status ${d.online?"online":"offline"}">${d.online?"Online":"Offline"}</span><p id="driver-gps-status" class="smallprint">During an accepted active ride, Transfer shares your live location with that customer. Keep the Driver panel open for foreground GPS updates.</p><button id="availability" class="btn driver-availability ${d.online?"is-online":"is-offline"}" ${!d.approved?'disabled':''}>${d.online?"Go Offline":"Go Online"}</button><button class="btn btn-outline" data-go="/driver/settings">Settings</button></div></div>${notificationsPanel()}<div class="grid"><div class="card"><h3>Driver application</h3><p class="hint">${d.approved?"Approved":d.applied?"Submitted · Awaiting admin review":"Not submitted"}</p><button class="btn btn-outline" data-go="/driver/settings?tab=application">Open application</button></div><div class="card"><h3>Driver app PIN</h3><p class="hint">Four-digit local device lock preference.</p><button class="btn btn-outline" id="pin-set">Set / change PIN</button></div></div>
<section class="section"><h2>Open booking requests</h2>${!d.approved?`<div class="notice">Your driver application must be approved by Admin before requests are shown.</div>`:!d.online?`<div class="notice">Go Online to view eligible booking requests.</div>`:bs.length?bs.map(b=>`<div class="card section"><b>${esc(b.kind)}</b><p>${esc(b.pickup)} → ${esc(b.dropoff)}</p><small class="hint">${esc(b.date||"As soon as possible")} ${esc(b.time||"")}</small><p><a class="btn btn-outline btn-small" href="${pickupMapUrl(b)}" target="_blank" rel="noopener">Open pickup in Google Maps ↗</a></p><form class="offer-form form-grid" data-booking="${b.id}"><div class="field"><label>Your price (SAR)</label><input name="price" type="number" min="1" required></div><div class="field"><label>Estimated pickup time</label><input name="eta" placeholder="e.g. 12 minutes"></div><div class="field full"><button class="btn btn-small">Send price offer</button></div></form></div>`).join(""):`<div class="empty">No open requests right now.</div>`}</section>
<section class="section"><h2>Your accepted rides & history</h2>${history.length?history.map(b=>{let o=state.offers.find(x=>x.id===b.acceptedOffer)||state.offers.find(x=>x.bookingId===b.id&&x.driverId===me().id&&x.status==='accepted');let next=b.status==='accepted'?'driver_arrived':b.status==='driver_arrived'?'in_progress':b.status==='in_progress'?'completed':null;let label=next==='driver_arrived'?'Mark arrived':next==='in_progress'?'Start ride':next==='completed'?'Complete ride':'';return `<div class="card section"><b>${esc(b.pickup)} → ${esc(b.dropoff)}</b><p><span class="pill">${esc(b.status.replaceAll('_',' '))}</span> · ${money(o?.price)}</p><button class="btn btn-outline btn-small" data-driver-chat="${b.id}">Open customer chat</button> ${next?`<button class="btn btn-small" data-trip-status="${b.id}" data-next="${next}">${label}</button>`:''}</div>`}).join(""):`<div class="empty">Accepted rides and completed trip history will appear here.</div>`}</section>${driverFinancePanel()}
<section class="section"><h2>Your submitted offers</h2>${state.offers.length?state.offers.map(o=>`<div class="offer"><div><b>${esc(o.vehicle)} · ${money(o.price)}</b><small>${esc(o.status)} · ${esc(o.eta||"")}</small></div></div>`).join(""):`<div class="empty">You have not sent any offers yet.</div>`}</section><section class="section card"><div class="section-title"><h2>Customer & Help Centre</h2><a class="btn btn-outline btn-small" href="mailto:Limuzin@196vip.si?subject=Transfer%20Driver%20Support">Message Help Centre</a></div><p class="hint">Message your customer from an accepted ride. For account, payment or app support, contact the Transfer Help Centre by email. Customer and driver phone numbers remain private.</p><div id="chat-area"><div class="empty">Open customer chat from an accepted ride above.</div></div></section>`}
function admin(){let ds=state.drivers;return `<div class="page-head"><div><div class="eyebrow">Administration</div><h1>Admin dashboard</h1><p>Review drivers, bookings, offers and service prices.</p></div><button class="btn btn-outline" data-go="/admin/settings">Settings</button></div>
<div class="statrow"><div class="stat"><b>${state.bookings.length}</b><span>Bookings</span></div><div class="stat"><b>${ds.length}</b><span>Driver applications</span></div><div class="stat"><b>${state.offers.length}</b><span>Offers</span></div></div>
<section class="section card"><h2>Driver applications</h2>${ds.length?ds.map((d,i)=>`<div class="offer"><div><b>${esc(d.legalName||d.email)}</b><small>${esc(d.vehicle||"Vehicle pending")} · ${esc(d.category||"Comfort")} · ${esc(d.status||"pending")}</small>${d.photo?`<img src="${esc(d.photo)}" alt="Driver vehicle" style="width:100px;height:68px;object-fit:cover;border-radius:8px">`:''}</div><button class="btn btn-small btn-outline" data-driver-toggle="${i}">${d.approved?"Disable":"Approve"}</button></div>`).join(""):`<div class="empty">No driver applications.</div>`}</section>
<section class="section card"><h2>All bookings & ride control</h2>${state.bookings.length?state.bookings.map(b=>{let next=b.status==='accepted'?'driver_arrived':b.status==='driver_arrived'?'in_progress':b.status==='in_progress'?'completed':null;return `<div class="offer"><div><b>${esc(b.kind)}</b><small>${esc(b.pickup)} → ${esc(b.dropoff)} · ${esc(b.status.replaceAll('_',' '))}</small></div><div>${next?`<button class="btn btn-small" data-trip-status="${b.id}" data-next="${next}">${next==='driver_arrived'?'Mark arrived':next==='in_progress'?'Start ride':'Complete ride'}</button>`:''}<button class="btn btn-small btn-outline" data-admin-cancel="${b.id}">Cancel</button></div>${b.status==='open'?`<form class="admin-fixed-form form-grid" data-booking="${b.id}"><div class="field"><label>Assign approved driver</label><select name="driver" required><option value="">Select driver</option>${state.drivers.filter(d=>d.approved).map(d=>`<option value="${d.id}">${esc(d.legalName||d.email||d.id)} · ${esc(d.vehicle||'Vehicle')}</option>`).join('')}</select></div><div class="field"><label>Fixed price (SAR)</label><input name="price" type="number" min="1" value="${b.category==='Business'?state.settings.business:b.category==='VIP'?state.settings.vip:state.settings.comfort}" required></div><div class="field full"><button class="btn btn-small">Create admin fixed offer</button></div></form>`:''}</div>`}).join(""):`<div class="empty">No bookings have been created.</div>`}</section>
<section class="section card"><h2>Manage offers</h2>${state.offers.length?state.offers.map(o=>`<div class="offer"><div><b>${esc(o.vehicle)} · ${money(o.price)}</b><small>${esc(o.driverEmail||o.driverId||"")} · ${esc(o.status)}</small></div>${o.status==='pending'?`<div class="field"><label>Override price (SAR)</label><input type="number" min="1" id="admin-price-${o.id}" value="${o.price}"></div><button class="btn btn-small" data-admin-override="${o.id}">Save price</button><button class="btn btn-small btn-outline" data-remove-offer="${o.id}">Remove offer</button>`:''}</div>`).join(""):`<div class="empty">No driver offers yet.</div>`}</section>
<section class="section card"><h2>Driver documents (private)</h2>${state.documents.length?state.documents.map(d=>`<div class="offer"><div><b>${esc(d.document_type.replaceAll('_',' '))}</b><small>Driver ${esc(d.driver_id)} · ${new Date(d.created_at).toLocaleString()}</small></div><button class="btn btn-small btn-outline" data-doc-open="${d.id}">Secure view</button></div>`).join(""):`<div class="empty">No uploaded driver documents.</div>`}</section>
${adminFinancePanel()}
<section class="section card"><h2>Fixed base prices (SAR)</h2><div class="form-grid">${["comfort","business","vip"].map(k=>`<div class="field"><label>${k[0].toUpperCase()+k.slice(1)}</label><input id="price-${k}" type="number" min="0" value="${state.settings[k]}"></div>`).join("")}</div><button id="save-prices" class="btn">Save base prices</button></section>`}
const settingSections={
customer:[["profile","Profile"],["preferences","Preferences"],["notifications","Notifications"],["security","Account security"]],
driver:[["profile","Personal profile"],["application","Driver application"],["vehicle","Vehicle & documents"],["preferences","Preferences"],["notifications","Notifications"],["security","PIN & security"]],
admin:[["profile","Admin profile"],["operations","Booking controls"],["notifications","Notifications"],["security","Security"]]
};
function settingsPage(r){let p=profile(),d=currentDriver();let tab=new URLSearchParams(location.search).get("tab")||settingsTab;if(!settingSections[r].some(x=>x[0]===tab))tab="profile";settingsTab=tab;
let nav=settingSections[r].map(([k,label])=>`<button class="${tab===k?"active":""}" data-setting-tab="${k}">${label}</button>`).join("");
let body="";
if(tab==="profile")body=`<h2>${r==="admin"?"Administrator profile":"Personal profile"}</h2><form id="profile-form"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" value="${esc(p.name||"")}" placeholder="Full name"></div><div class="field"><label>Email address</label><input value="${esc(me().email)}" disabled></div><div class="field"><label>Phone number (private)</label><input name="phone" type="tel" value="${esc(p.phone||"")}" placeholder="+966…"></div><div class="field"><label>Country</label><input name="country" value="${esc(p.country||"")}" placeholder="Country"></div><div class="field full"><label>Profile photo</label><input name="photo" type="file" accept="image/*"><img class="preview-img ${p.photo?"":"hidden"}" id="profile-preview" src="${p.photo||""}"></div></div><button class="btn">Save profile</button></form><p class="smallprint">Your email is your sign-in identity. Phone number is private and must never be exposed to other users.</p>`;
if(tab==="preferences")body=`<h2>App preferences</h2><div class="field"><label>Language</label><select id="pref-language"><option>English</option><option>العربية</option><option>اردو</option></select></div><div class="field"><label>Display currency</label><select id="pref-currency"><option>SAR</option><option>USD</option><option>EUR</option><option>GBP</option></select></div><div class="field"><label>Time zone</label><select id="pref-timezone"><option>Automatic</option><option>Asia/Riyadh</option><option>UTC</option></select></div><button id="save-preferences" class="btn">Save preferences</button><p class="smallprint">Language and currency selection are saved as preview preferences. Currency conversion is not active.</p>`;
if(tab==="notifications")body=`<h2>Notification settings</h2>${["Booking updates","New driver offers","Chat messages","Driver request alerts","Promotional updates"].map((x,i)=>`<label class="checkrow"><span>${x}</span><input type="checkbox" data-notify="${i}" ${p.notifications?.[i]!==false?"checked":""}></label>`).join("")}<button id="save-notifications" class="btn" style="margin-top:16px">Save notifications</button><p class="smallprint">These are saved preferences only. Real push/email notifications will be enabled through backend setup.</p>`;
if(tab==="security")body=`<h2>Driver app lock</h2><div class="notice">Set a four-digit PIN. The driver panel will ask for it whenever this app is opened or refreshed on this device.</div><p>Signed-in account: <b>${esc(me().email)}</b></p><p><b>${localStorage.getItem(driverPinKey(me().email))?"PIN lock is ON":"PIN lock is OFF"}</b></p><button id="security-pin" class="btn btn-outline">${localStorage.getItem(driverPinKey(me().email))?"Change driver PIN":"Set driver PIN"}</button>${localStorage.getItem(driverPinKey(me().email))?` <button id="security-pin-remove" class="btn btn-quiet" type="button">Turn off PIN lock</button>`:""}<p class="smallprint">This is a local device privacy lock, not a replacement for your phone lock or secure account authentication. Anyone with access to browser storage may be able to bypass it. It applies only to the driver app.</p>`;
if(tab==="application")body=`<h2>Driver application</h2><form id="application-form"><div class="form-grid"><div class="field"><label>Legal full name</label><input name="legalName" value="${esc(d.legalName||p.name||"")}" required></div><div class="field"><label>Country of operation</label><input name="country" value="${esc(d.country||"")}" placeholder="Saudi Arabia" required></div><div class="field"><label>Driving licence number</label><input name="licence" value="${esc(d.licence||"")}" required></div><div class="field"><label>Licence expiry date</label><input name="licenceExpiry" type="date" value="${esc(d.licenceExpiry||"")}"></div><div class="field"><label>Driver licence document</label><input name="licenceDoc" type="file" accept="image/*,.pdf"></div><div class="field"><label>National ID / Iqama document</label><input name="identityDoc" type="file" accept="image/*,.pdf"></div><div class="field full"><label>Additional notes</label><textarea name="notes">${esc(d.notes||"")}</textarea></div></div><button class="btn">Submit driver application</button></form><p class="smallprint">The application details are saved in Supabase. Licence and identity files are uploaded to private Supabase Storage. Only the driver and Admin can view them.</p>`;
if(tab==="vehicle")body=`<h2>Vehicle & documents</h2><form id="vehicle-form"><div class="form-grid"><div class="field"><label>Make / model</label><select name="vehicle" required><option value="">Select vehicle</option>${["GMC Yukon","GMC Tahoe","Lexus","Ford Taurus","Mercedes Vito","Mercedes Sprinter","Toyota Hiace","Toyota Coaster"].map(v=>`<option ${d.vehicle===v?"selected":""}>${v}</option>`).join("")}</select></div><div class="field"><label>Year</label><input name="year" type="number" min="1990" max="2035" value="${esc(d.year||"")}"></div><div class="field"><label>Category</label><select name="category"><option ${d.category==="Comfort"?"selected":""}>Comfort</option><option ${d.category==="Business"?"selected":""}>Business</option><option ${d.category==="VIP"?"selected":""}>VIP</option></select></div><div class="field"><label>Vehicle plate (private)</label><input name="plate" value="${esc(d.plate||"")}"></div><div class="field"><label>Vehicle photo</label><input name="photo" type="file" accept="image/*"></div><div class="field"><label>Vehicle registration document</label><input name="registration" type="file" accept="image/*,.pdf"></div><div class="field"><label>Insurance document</label><input name="insurance" type="file" accept="image/*,.pdf"></div><div class="field"><label>Driver licence image</label><input name="licenceFile" type="file" accept="image/*,.pdf"></div></div><button class="btn">Save vehicle details</button></form><p class="smallprint">Vehicle details are saved in Supabase. Vehicle photos are saved in Supabase Storage. Registration, insurance and licence files are private and visible only to the driver and Admin.</p>`;
if(tab==="operations")body=`<h2>Booking & platform controls</h2><label class="checkrow"><span>Allow driver price offers</span><input id="admin-offers" type="checkbox" ${state.settings.offersEnabled?"checked":""}></label>
<p class="smallprint">The customer has the Bell controls for new booking and assigned-driver alerts. Drivers receive alerts and reply through chat; they do not have a Bell button.</p>
<p class="smallprint">Customers and drivers can use private in-app chat after an offer is accepted. Phone numbers remain private.</p><div class="field"><label>Default customer offer limit</label><select id="offer-limit"><option ${Number(state.settings.offerLimit||4)===4?"selected":""}>4</option><option ${Number(state.settings.offerLimit||4)===3?"selected":""}>3</option><option ${Number(state.settings.offerLimit||4)===2?"selected":""}>2</option></select></div><div class="field"><label>Default pricing mode</label><select id="pricing-mode"><option ${state.settings.pricingMode==="driver_offers"?"selected":""}>Driver offers</option><option ${state.settings.pricingMode==="admin_fixed"?"selected":""}>Admin fixed price</option><option ${state.settings.pricingMode==="both"?"selected":""}>Driver offers + admin override</option></select></div><button id="save-operations" class="btn">Save controls</button><p class="smallprint">Offer enable/disable and pricing mode are saved in Supabase. Booking and chat alerts are stored in the app notification inbox.</p>`;
return `<div class="page-head"><div><div class="eyebrow">${r} settings</div><h1>Settings</h1><p>Manage your ${r} account and app preferences.</p></div><button class="btn btn-outline" data-go="/${r}">Back to dashboard</button></div><div class="settings-layout"><nav class="settings-nav">${nav}</nav><section class="card settings-panel">${body}</section></div>`}
function render(){header();let r=role(),s=me(),isSettings=location.pathname.endsWith("/settings");
if(r==="driver"&&s&&s.role==="driver"&&!localStorage.getItem(driverPinKey(s.email))&&!localStorage.getItem("transfer_driver_pin_v1_"+String(s.email||"").toLowerCase())){app.innerHTML=`<section class="auth-wrap"><div class="card" style="max-width:420px;margin:8vh auto;text-align:center"><div class="eyebrow">DRIVER SECURITY</div><h1>Create your driver PIN</h1><p class="hint">Set a four-digit PIN to protect the Driver workspace on this device.</p><form id="driver-pin-create"><div class="field"><label>Four-digit PIN</label><input id="driver-pin-new" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required></div><div class="field"><label>Confirm PIN</label><input id="driver-pin-confirm" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required></div><button class="btn" type="submit">Save PIN and continue</button></form><p id="driver-pin-create-error" class="smallprint" role="alert"></p></div></section>`;const f=$("#driver-pin-create");f.onsubmit=async e=>{e.preventDefault();const a=$("#driver-pin-new").value,b=$("#driver-pin-confirm").value;if(!/^\d{4}$/.test(a)||a!==b){$("#driver-pin-create-error").textContent="PINs must match and contain exactly four digits.";return}localStorage.setItem(driverPinKey(s.email),JSON.stringify(await hashDriverPin(a)));driverPinUnlocked=true;render()};header();return}
if(r==="driver"&&s&&s.role==="driver"&&localStorage.getItem(driverPinKey(s.email))&&!driverPinUnlocked){app.innerHTML=`<section class="auth-wrap"><div class="card" style="max-width:420px;margin:8vh auto;text-align:center"><div class="eyebrow">DRIVER SECURITY</div><h1>Enter your driver PIN</h1><p class="hint">This driver app is locked on this device.</p><form id="driver-pin-unlock"><div class="field"><label>Four-digit PIN</label><input id="driver-pin-entry" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{4}" maxlength="4" required placeholder="••••" style="text-align:center;letter-spacing:.5em;font-size:1.4rem"></div><button class="btn" type="submit">Unlock Transfer</button></form><p id="driver-pin-error" class="smallprint" role="alert"></p><button id="driver-pin-signout" class="btn btn-quiet" type="button">Sign out</button></div></section>`;bindDriverPinLock();header();return}
if(r==="home")app.innerHTML=home();else if(r==="choose"&&s)app.innerHTML=roleChooser();else if(!s)app.innerHTML=auth(r);else if(s.role!==r)app.innerHTML=`<section class="card"><h1>Access not authorized</h1><p class="hint">This signed-in account does not have permission to open this panel.</p><button class="btn" data-go="/${s.role}">Open my authorized panel</button></section>`;else if(isSettings)app.innerHTML=settingsPage(r);else app.innerHTML=r==="customer"?customer():r==="driver"?driver():admin();if(s&&s.role===r&&r!=="home")app.insertAdjacentHTML("beforeend",`<nav class="role-nav" aria-label="Main navigation"><button data-go="/${r}" class="${!isSettings?"active":""}">Dashboard</button><button data-go="/${r}/settings" class="${isSettings?"active":""}">Settings</button></nav>`);bind();header()}
function bindDriverPinLock(){const f=$("#driver-pin-unlock");if(f)f.onsubmit=async e=>{e.preventDefault();const entered=$("#driver-pin-entry").value;if(await verifyDriverPin(entered)){driverPinUnlocked=true;render()}else{$("#driver-pin-error").textContent="Incorrect PIN. Please try again.";$("#driver-pin-entry").value="";$("#driver-pin-entry").focus()}};const out=$("#driver-pin-signout");if(out)out.onclick=async()=>{driverPinUnlocked=false;await stopDriverGps();if(sb)await sb.auth.signOut();state.session=null;authUser=null;authProfile=null;go("/")}}
function bind(){
 if(me()?.role==='driver'&&currentDriver().online&&currentDriver().approved)startDriverGps();else if(driverGpsWatch!==null)stopDriverGps();
 if(me()?.role==='customer')initTrackingMaps();
$$(`[data-select-role]`).forEach(x=>x.onclick=async()=>{const chosen=x.dataset.selectRole;if(!["customer","driver"].includes(chosen)||!me()?.id)return;try{const {error}=await sb.from("vip_profiles").update({account_type:chosen}).eq("id",me().id);dbError(error);state.session.role=chosen;save();await refreshData(true);startLiveUpdates();go("/"+chosen)}catch(err){alert("Could not save your account choice: "+err.message)}});const chooseOut=$("#choose-signout");if(chooseOut)chooseOut.onclick=async()=>{if(sb)await sb.auth.signOut();state.session=null;authUser=null;authProfile=null;go("/")};
$$(`[data-go]`).forEach(x=>x.onclick=e=>{e.preventDefault();go(x.dataset.go)});
let af=$("#auth-form");if(af)af.onsubmit=e=>{e.preventDefault();beginEmailOtp(af)};
 let of=$("#otp-form");if(of)of.onsubmit=e=>{e.preventDefault();verifyEmailOtp(of)};
 let resend=$("#resend-otp");if(resend)resend.onclick=async()=>{if(!window.transferOtpEmail)return;const {error}=await sb.auth.signInWithOtp({email:window.transferOtpEmail,options:{shouldCreateUser:true,data:window.transferOtpMeta||{}}});showAuthError(error?error.message:"A new OTP has been sent.")};
$$("[data-kind]").forEach(x=>x.onclick=()=>{$$("[data-kind]").forEach(y=>y.classList.remove("active"));x.classList.add("active");let f=$("#booking-form");f.kind.value=x.dataset.kind;$$(".later-field").forEach(y=>y.classList.toggle("hidden",x.dataset.kind==="Now Booking"));if(x.dataset.kind==="Later Booking")$$(".later-field").forEach(y=>y.classList.remove("hidden"))});

let pickupAddress=$("#pickup-address"),pickupMap=null,pickupMarker=null;
const setPickupPoint=async(lat,lng,reverse=true)=>{ $("#pickup-lat").value=lat;$("#pickup-lng").value=lng;if(pickupMarker)pickupMarker.setLatLng([lat,lng]);if(pickupMap)pickupMap.setView([lat,lng],15);if(reverse&&pickupAddress){try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}`);if(r.ok){const j=await r.json();if(j.display_name)pickupAddress.value=j.display_name;}}catch(e){} }const st=$("#pickup-location-status");if(st)st.textContent=`Pickup point selected (${Number(lat).toFixed(5)}, ${Number(lng).toFixed(5)}).`;};
const mapBox=$("#pickup-map");if(mapBox&&window.L){pickupMap=L.map(mapBox,{scrollWheelZoom:false}).setView([24.7136,46.6753],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(pickupMap);pickupMarker=L.marker([24.7136,46.6753],{draggable:true}).addTo(pickupMap);pickupMarker.on('dragend',e=>{const q=e.target.getLatLng();setPickupPoint(q.lat,q.lng,true)});pickupMap.on('click',e=>setPickupPoint(e.latlng.lat,e.latlng.lng,true));const la=Number($("#pickup-lat")?.value),lo=Number($("#pickup-lng")?.value);if(Number.isFinite(la)&&Number.isFinite(lo)&&la!==0&&lo!==0){pickupMap.setView([la,lo],15);pickupMarker.setLatLng([la,lo]);}}
if(pickupAddress)pickupAddress.addEventListener("change",async()=>{const q=pickupAddress.value.trim();if(!q)return;try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q=${encodeURIComponent(q)}`);const a=await r.json();if(a?.[0])await setPickupPoint(Number(a[0].lat),Number(a[0].lon),false);else {$("#pickup-lat").value="";$("#pickup-lng").value="";}}catch(e){console.warn('Address lookup failed',e)}});
let locBtn=$("#use-pickup-location");if(locBtn)locBtn.onclick=()=>{let status=$("#pickup-location-status");if(!navigator.geolocation){status.textContent="Location is not supported by this browser. Please type the pickup address.";return}status.textContent="Getting your current GPS location…";navigator.geolocation.getCurrentPosition(pos=>{setPickupPoint(pos.coords.latitude,pos.coords.longitude,true);},err=>{status.textContent="Could not get location: "+err.message+". Please select a point on the map or type an address."},{enableHighAccuracy:true,timeout:20000,maximumAge:0})};
let bf=$("#booking-form");if(bf)bf.onsubmit=async e=>{e.preventDefault();let f=new FormData(bf),kind=f.get("kind");if(kind==="Later Booking"&&(!f.get("date")||!f.get("time"))){alert("Please choose the pickup date and time.");return}try{let pickupAt=null;if(f.get("date")&&f.get("time")){let dt=new Date(`${f.get("date")}T${f.get("time")}`);if(!isNaN(dt))pickupAt=dt.toISOString()}let booking=await submitBooking({kind,pickup:f.get("pickup"),pickupLat:f.get("pickupLat")?Number(f.get("pickupLat")):null,pickupLng:f.get("pickupLng")?Number(f.get("pickupLng")):null,dropoff:f.get("dropoff"),pickupAt,category:f.get("category"),passengers:parseInt(f.get("passengers"),10)||1});alert("Your booking has been saved. Approved online drivers can now see it.");await refreshData();}catch(err){alert("Booking could not be saved: "+err.message)}};
$$("[data-accept]").forEach(x=>x.onclick=async()=>{let o=state.offers.find(y=>y.id===x.dataset.accept),b=state.bookings.find(y=>y.id===o?.bookingId);if(!o||!b)return;try{await acceptOffer(b,o);alert("Offer accepted. The selected vehicle plate is now available for this booking.");await refreshData()}catch(err){alert("Could not accept offer: "+err.message)}});
$$("[data-cancel-booking],[data-admin-cancel]").forEach(x=>x.onclick=async()=>{let id=x.dataset.cancelBooking||x.dataset.adminCancel;try{await cancelBooking(id);await refreshData()}catch(err){alert("Could not cancel booking: "+err.message)}});
$$(`[data-bell-booking]`).forEach(x=>x.onclick=async()=>{try{const {error}=await sb.rpc("vip_customer_alert_drivers",{p_booking_id:x.dataset.bellBooking});dbError(error);alert("Eligible online drivers have been alerted.")}catch(err){alert("Driver alert failed: "+err.message)}});
$$("[data-chat]").forEach(x=>x.onclick=()=>openChat(x.dataset.chat,"customer"));
$$("[data-driver-chat]").forEach(x=>x.onclick=()=>openChat(x.dataset.driverChat,"driver"));
let av=$("#availability");if(av)av.onclick=async()=>{let d=currentDriver();try{await updateAvailability(!d.online);await refreshData()}catch(err){alert("Availability change failed: "+err.message)}};
function putDriver(d){let i=state.drivers.findIndex(x=>x.email===me().email);if(i<0)state.drivers.push(d);else state.drivers[i]=d;save()}
$$(".offer-form").forEach(f=>f.onsubmit=async e=>{e.preventDefault();if(!state.settings.offersEnabled||state.settings.pricingMode==="admin_fixed"){alert("Driver offers are currently disabled by Admin.");return}let d=currentDriver();if(!d.approved||!d.online){alert("Your driver profile must be approved and online before sending an offer.");return}let fd=new FormData(f),b=state.bookings.find(x=>x.id===f.dataset.booking);try{await submitDriverOffer(b,Number(fd.get("price")),fd.get("eta"));alert("Your price offer has been saved and is now available to the customer.");await refreshData()}catch(err){alert("Offer could not be sent: "+err.message)}});
$$("[data-setting-tab]").forEach(x=>x.onclick=()=>{settingsTab=x.dataset.settingTab;history.replaceState({},"",location.pathname+"?tab="+settingsTab);render()});
let pf=$("#profile-form");if(pf)pf.onsubmit=async e=>{e.preventDefault();let fd=new FormData(pf),p={name:fd.get("name"),phone:fd.get("phone"),country:fd.get("country")};try{const {error}=await sb.from("vip_profiles").update({full_name:String(p.name||""),phone:String(p.phone||"")}).eq("id",me().id);dbError(error);setProfile(p);alert("Profile saved securely.");render()}catch(err){alert("Profile could not be saved: "+err.message)}};
let appf=$("#application-form");if(appf)appf.onsubmit=async e=>{e.preventDefault();let fd=new FormData(appf);try{const row={driver_id:me().id,vehicle_category:currentDriver().category||'Comfort',vehicle_model:currentDriver().vehicle||'Not provided',vehicle_year:currentDriver().year?Number(currentDriver().year):null,vehicle_plate:currentDriver().plate||null,notes:[`Legal name: ${fd.get('legalName')}`,`Country: ${fd.get('country')}`,`Licence number: ${fd.get('licence')}`,`Licence expiry: ${fd.get('licenceExpiry')||'Not supplied'}`,String(fd.get('notes')||'')].join(' · '),status:'pending'};const {error}=await sb.from('vip_driver_applications').upsert(row,{onConflict:'driver_id'});dbError(error);await saveDriverDocument('driver_licence',fd.get('licenceDoc'));await saveDriverDocument('national_id_iqama',fd.get('identityDoc'));alert("Driver application and selected documents have been securely saved in Supabase. Admin review is required.");await refreshData()}catch(err){alert("Application or document upload failed: "+err.message)}};
let vf=$("#vehicle-form");if(vf)vf.onsubmit=async e=>{e.preventDefault();let fd=new FormData(vf);try{let photoPath=await uploadStorageFile('transfer-vehicle-photos',fd.get('photo'),'vehicle');let photoUrl=photoPath?sb.storage.from('transfer-vehicle-photos').getPublicUrl(photoPath).data.publicUrl:null;const row={driver_id:me().id,category:fd.get('category'),model:fd.get('vehicle'),plate:fd.get('plate')||null,photo_url:photoUrl||currentDriver().photo||null};const {data:existing,error:fe}=await sb.from('vip_vehicles').select('id,approved').eq('driver_id',me().id).limit(1).maybeSingle();dbError(fe);let result;if(existing){result=await sb.from('vip_vehicles').update(row).eq('id',existing.id);dbError(result.error)}else{const {data:application,error:ae}=await sb.from('vip_driver_applications').select('id,status').eq('driver_id',me().id).maybeSingle();dbError(ae);if(application?.status==='approved'){result=await sb.from('vip_vehicles').insert({...row,approved:true});dbError(result.error)}else{const {error:ue}=await sb.from('vip_driver_applications').update({vehicle_category:row.category,vehicle_model:row.model,vehicle_plate:row.plate,vehicle_photo_url:photoUrl||null}).eq('driver_id',me().id);dbError(ue)}}await saveDriverDocument('vehicle_registration',fd.get('registration'));await saveDriverDocument('vehicle_insurance',fd.get('insurance'));await saveDriverDocument('driver_licence',fd.get('licenceFile'));alert("Vehicle details, photo and selected documents have been saved in Supabase. Admin approval is required before the driver can go online.");await refreshData()}catch(err){alert("Vehicle or document upload failed: "+err.message)}};
let sn=$("#save-notifications");if(sn)sn.onclick=()=>{let p={...profile(),notifications:$$("[data-notify]").map(x=>x.checked)};setProfile(p);alert("Notification preferences saved in preview.")};
let sp=$("#save-preferences");if(sp)sp.onclick=()=>{setProfile({language:$("#pref-language").value,currency:$("#pref-currency").value,timezone:$("#pref-timezone").value});alert("Preferences saved in preview.")};
let so=$("#save-operations");if(so)so.onclick=async()=>{try{const mode=$("#pricing-mode").value==='Admin fixed price'?'admin_fixed':$("#pricing-mode").value==='Driver offers + admin override'?'both':'driver_offers';const {error}=await sb.from('vip_settings').update({offers_enabled:$("#admin-offers").checked,pricing_mode:mode}).eq('id',1);dbError(error);alert("Booking and offer controls saved in Supabase. New booking alerts are automatic for approved online drivers.");await refreshData()}catch(err){alert("Settings could not be saved: "+err.message)}};
let tog=$("#toggle-offers");if(tog)tog.onclick=async()=>{try{const {error}=await sb.from('vip_settings').update({offers_enabled:!state.settings.offersEnabled}).eq('id',1);dbError(error);await refreshData()}catch(err){alert(err.message)}};
let prices=$("#save-prices");if(prices)prices.onclick=async()=>{try{const {error}=await sb.from('vip_settings').update({comfort_price:Number($("#price-comfort").value),business_price:Number($("#price-business").value),vip_price:Number($("#price-vip").value)}).eq('id',1);dbError(error);alert("Base prices saved in Supabase.");await refreshData()}catch(err){alert("Prices could not be saved: "+err.message)}};
$$('[data-save-commission]').forEach(x=>x.onclick=async()=>{const id=x.dataset.saveCommission,sel=$(`[data-commission-driver="${id}"]`);if(!sel||!['5','10'].includes(sel.value)){alert('Choose 5% or 10% first.');return}try{const {error}=await sb.rpc('vip_admin_set_driver_commission',{p_driver_id:id,p_percent:Number(sel.value)});dbError(error);alert('Driver commission rate saved.');await refreshData()}catch(err){alert('Commission rate could not be saved: '+err.message)}});
$$("[data-driver-toggle]").forEach(x=>x.onclick=async()=>{let d=state.drivers[Number(x.dataset.driverToggle)];if(!d)return;try{let status=d.approved?'disabled':'approved';const {error}=await sb.rpc('vip_admin_set_driver_status',{p_driver_id:d.id,p_status:status});dbError(error);alert(status==='approved'?'Driver approved. The driver can now sign in to Driver panel.':'Driver disabled.');await refreshData()}catch(err){alert("Driver status could not be changed: "+err.message)}});
$$('.admin-fixed-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const fd=new FormData(f);try{const {error}=await sb.rpc('vip_admin_create_fixed_offer',{p_booking_id:f.dataset.booking,p_driver_id:fd.get('driver'),p_price:Number(fd.get('price'))});dbError(error);alert('Admin fixed-price offer created and notifications sent.');await refreshData()}catch(err){alert('Fixed offer could not be created: '+err.message)}});
$$('[data-admin-override]').forEach(x=>x.onclick=async()=>{const input=$('#admin-price-'+x.dataset.adminOverride);try{const {error}=await sb.rpc('vip_admin_set_offer_price',{p_offer_id:x.dataset.adminOverride,p_price:Number(input?.value)});dbError(error);alert('Offer price updated.');await refreshData()}catch(err){alert('Offer price could not be updated: '+err.message)}});
$$("[data-remove-offer]").forEach(x=>x.onclick=async()=>{if(!confirm("Remove this driver offer from the booking?"))return;try{await removeOffer(x.dataset.removeOffer);alert("Offer removed in the database.");await refreshData()}catch(err){alert("Offer could not be removed: "+err.message)}});
$$("[data-trip-status]").forEach(x=>x.onclick=async()=>{try{let cashCollected=false;if(x.dataset.next==='completed'){const answer=prompt('At drop-off, was the full customer cash fare collected? Type YES or NO.','YES');if(answer===null)return;const normalized=answer.trim().toUpperCase();if(!['YES','NO'].includes(normalized)){alert('Please type YES or NO.');return}cashCollected=normalized==='YES';}await updateRideStatus(x.dataset.tripStatus,x.dataset.next,cashCollected);alert(x.dataset.next==='completed'?'Ride completed. Fare, cash status and commission have been recorded.':'Ride status saved in Supabase.');await refreshData()}catch(err){alert("Ride status could not be updated: "+err.message)}});
$$('[data-read-notification]').forEach(x=>x.onclick=async()=>{try{const {error}=await sb.from('vip_notifications').update({is_read:true}).eq('id',x.dataset.readNotification);dbError(error);await refreshData()}catch(err){alert(err.message)}});
$$('[data-doc-open]').forEach(x=>x.onclick=async()=>{try{let d=state.documents.find(z=>z.id===x.dataset.docOpen);if(!d)return;const {data,error}=await sb.storage.from('transfer-driver-documents').createSignedUrl(d.file_path,300);dbError(error);window.open(data.signedUrl,'_blank','noopener')}catch(err){alert('Document could not be opened: '+err.message)}});
$$(".rating-form").forEach(f=>f.onsubmit=e=>{e.preventDefault();let b=state.bookings.find(y=>y.id===f.dataset.rating);if(!b)return;let fd=new FormData(f);b.rating={stars:Number(fd.get("stars")),comment:fd.get("comment")};save();alert("Thank you. Your driver rating was saved in this preview.");render()});
let pin=$("#security-pin");if(pin)pin.onclick=async()=>{const key=driverPinKey(me()?.email),old=localStorage.getItem(key),legacy=localStorage.getItem("transfer_driver_pin_v1_"+String(me()?.email||"").toLowerCase());if((old||legacy)&&!await verifyDriverPin(prompt("Enter your current four-digit PIN")||"")){alert("Current PIN is incorrect.");return}let v=prompt("Choose a new four-digit driver PIN");if(v===null)return;if(!/^\d{4}$/.test(v)){alert("PIN must contain exactly four digits.");return}localStorage.setItem(key,JSON.stringify(await hashDriverPin(v)));localStorage.removeItem("transfer_driver_pin_v1_"+String(me()?.email||"").toLowerCase());driverPinUnlocked=true;alert("Driver PIN lock is now enabled on this device.");render()};
let removePin=$("#security-pin-remove");if(removePin)removePin.onclick=async()=>{if(!await verifyDriverPin(prompt("Enter your current four-digit PIN to turn off the lock")||"")){alert("Incorrect PIN.");return}localStorage.removeItem(driverPinKey(me()?.email));driverPinUnlocked=true;alert("Driver PIN lock turned off.");render()};
}
async function boot(){
 if(!sb){render();return}
 const {data:{session},error}=await sb.auth.getSession();
 if(error){render();return}
 if(session?.user){try{await loadVerifiedProfile(session.user);if(state.session.role==="admin"){await refreshData(true);startLiveUpdates();if(role()!=="admin")go("/admin");else render()}else if(role()==="home"||role()==="choose"){go("/choose")}else if(role()!==state.session.role){go("/"+state.session.role)}else{await refreshData(true);startLiveUpdates();render()}}catch(e){state.session=null;render();showAuthError(e.message)}}else render();
 sb.auth.onAuthStateChange((event,session)=>{if(event==="SIGNED_OUT"){authUser=null;authProfile=null;state.session=null;if(liveChannel)sb.removeChannel(liveChannel);render()}else if(event==="TOKEN_REFRESHED"&&session?.user){authUser=session.user}});
}
boot();
})();